const lRest=`<section class="wrap"><div id="catalogue-results" class="l-results" hidden aria-live="polite"></div><div class="l-shortcuts"><a href="#join">Get a library card ${arrow}</a><a href="#visit">Plan your visit ${arrow}</a><a href="#events">Find your people ${arrow}</a></div></section><section class="wrap l-events" id="events"><div class="l-section-top"><h2>A little something<br>for everyone.</h2><a class="line-link" href="#event-list">See all events ${arrow}</a></div><div class="l-event-grid" id="event-list"><article class="l-event"><div class="date">NOVEMBER<strong>07</strong></div><div><h3>Small ears.<br>Big adventures.</h3><p class="time">Storytime · Ages 3–6 · 10:30 am</p></div></article><article class="l-event"><div class="date">NOVEMBER<strong>12</strong></div><div><h3>The good<br>conversation club.</h3><p class="time">Book club · Adults · 6:00 pm</p></div></article><article class="l-event"><div class="date">NOVEMBER<strong>16</strong></div><div><h3>Make a little<br>room for making.</h3><p class="time">Paper workshop · All ages · 2:00 pm</p></div></article></div><p class="footnote" style="margin-top:15px">Illustrative event programme for this fictional library.</p></section><section class="l-books"><div class="wrap l-books-grid"><div><span class="eyebrow">On our reading table</span><h2 style="margin-top:23px">One more chapter.</h2><p class="intro">A few books to open a door, change the subject, or keep you company.</p><a class="line-link" href="#catalogue">Find a book ${arrow}</a></div><div>${[['A Room of One’s Own','Virginia Woolf','Essays'],['The Secret Garden','Frances Hodgson Burnett','Fiction'],['The Wind in the Willows','Kenneth Grahame','Children']].map(([title,author,tag])=>`<article class="l-book-row"><div class="book-spine" aria-hidden="true">${title}</div><div><h3>${title}</h3><p>${author}</p></div><span class="tag">${tag}</span></article>`).join('')}<p class="footnote" style="margin-top:15px">Reading suggestions; catalogue availability is demo data. Typographic book covers are illustrative.</p></div></div></section><section class="wrap l-visit" id="visit"><div><span class="eyebrow">A place to pause</span><h2 style="margin-top:22px">Come as you are.<br>Stay a while.</h2><p>Find a quiet corner, bring a question, or follow your curiosity. The library is a place for reading, learning and being together.</p><a class="line-link" href="#join">Make yourself a member ${arrow}</a></div><div class="l-hours"><span class="eyebrow">Illustrative opening hours</span><div><span>Monday–Friday</span><span>9 am–7 pm</span></div><div><span>Saturday</span><span>10 am–5 pm</span></div><div><span>Sunday</span><span>11 am–4 pm</span></div><p class="footnote" style="margin-top:18px">Location and access details would be confirmed with the real library before publication.</p></div></section><footer class="l-footer" id="join"><div class="wrap"><div class="l-membership"><div><h2 style="font:36px Georgia,serif">Your library. Your next chapter.</h2><p style="font-size:13px;margin-top:12px">Leave an email to try the membership-interest flow.</p></div><form id="membership"><label for="member-email">Email address<input id="member-email" type="email" required autocomplete="email" placeholder="you@example.com"></label><button class="btn" type="submit">I'm interested ${arrow}</button></form></div><p id="member-status" role="status" style="margin-top:14px;font-size:12px"></p><p class="demo-note">Local design study. Willow is fictional; programme, hours and catalogue availability are illustrative. Library photograph: <a href="https://unsplash.com/photos/xYyJAC0IdyI">Zetong Li / Unsplash</a>, used under the Unsplash License. It does not depict Willow premises.</p></div></footer>`;
