const nRest=`<div class="wrap n-values"><article><h3>Time to feel at ease</h3><p>Tell us what worries you. Your first conversation starts with listening.</p></article><article><h3>Clarity before treatment</h3><p>Discuss your options and costs before deciding what comes next.</p></article><article><h3>Your pace matters</h3><p>Ask for an explanation, a pause, or a little more time.</p></article></div><section class="wrap n-services" id="care"><div class="n-section-top"><div><span class="eyebrow">Care, considered</span><h2 style="margin-top:20px">Good care starts<br>with understanding.</h2></div><p>Every smile has a story. We begin with yours, then help you understand the care that may suit you.</p></div><div class="n-service-grid">${nServices.map(([title,copy],i)=>`<article class="n-service"><span class="number">0${i+1}</span><div><h3>${title}</h3><p>${copy}</p><a class="line-link" href="#appointment">Ask about this care ${arrow}</a></div></article>`).join('')}</div></section><section class="n-first" id="first-visit"><div class="wrap n-first-inner"><figure><img src="assets/dental-room-katarzyna.jpg" alt="Illustrative dental room, not Noor premises"><figcaption class="footnote" style="margin-top:8px">Illustrative room photo · Katarzyna Zygnerska / Unsplash</figcaption></figure><div><span class="eyebrow">Your first visit</span><h2>Nothing to rush.<br>Everything to ask.</h2>${[['A conversation first','Tell us about your health, your concerns and what you would like help with.'],['A clearer picture','Discuss an assessment, what it may involve and any next steps.'],['A decision, together','Talk through the options, expected costs and timing before agreeing to care.']].map(([t,c],i)=>`<div class="n-step"><span>0${i+1}</span><div><h3>${t}</h3><p>${c}</p></div></div>`).join('')}</div></div></section><section class="wrap n-faq" id="questions"><div><span class="eyebrow">It's okay to ask</span><h2 style="margin-top:20px">A few things<br>on your mind.</h2></div><div><details><summary>I feel nervous about visiting. Can I tell you?</summary><p>Yes. Include a note in your appointment request so the team can discuss your concerns with you before the visit.</p></details><details><summary>Will I know the cost before treatment?</summary><p>Ask for a clear explanation of proposed treatment and an estimate before making a decision. This demo does not publish prices or treatment promises.</p></details><details><summary>Can I request a visit in Urdu?</summary><p>Choose Urdu as your preferred language in the request below. A real clinic would confirm language availability when arranging your visit.</p></details></div></section><section class="n-booking" id="appointment"><div class="wrap n-booking-inner"><div><span class="eyebrow">One small next step</span><h2 style="margin-top:25px">Let's make room<br>for your smile.</h2><p>Tell us a little about yourself and your preferred visit. An appointment is confirmed only after the clinic contacts you.</p><p lang="ur" dir="rtl" style="text-align:left;font-size:18px">آئیے، بات سے آغاز کرتے ہیں۔</p></div><form class="n-form" id="appointment-form"><label>Your name<input name="name" required autocomplete="name" placeholder="Full name"></label><label>Phone number<input name="phone" required type="tel" autocomplete="tel" placeholder="03XX XXX XXXX"></label><label>Preferred day<input name="day" type="date" required></label><label>Preferred language<select name="language"><option>English</option><option>Urdu</option></select></label><label class="wide">What would you like to talk about?<select name="reason"><option>My first visit</option>Everyday dental care</option>Restorative care</option>Smile options</option>I'm feeling anxious</option></select></label><button class="btn wide" type="submit">Request an appointment ${arrow}</button><p class="wide" id="appointment-status" role="status">Local demo only. Details stay in this page; no appointment is sent.</p></form></div></section><footer class="wrap"><div class="n-footer"><a href="#main" class="n-logo">noor<small>Dental · Lahore</small></a><span style="font:20px Georgia,serif">Care begins with listening.</span></div><p class="demo-note">Fictional clinic used for local design evaluation. Content describes the proposed experience, not verified services or clinical outcomes. Stock photos do not depict Noor's premises or team. Room: <a href="https://unsplash.com/photos/44jaETSVX2I">Katarzyna Zygnerska</a>; consultation: <a href="https://unsplash.com/photos/Bg81yWKZlMg">Harold Hisona</a>. Unsplash License.</p></footer>`;
for(const v of ['a','b','c']){const hero=v==='c'?`<section class="wrap n-hero">${nCopy}<figure><img src="assets/dental-room-katarzyna.jpg" alt="Illustrative bright dental treatment room with a chair beside a window"><figcaption>Illustrative room · Katarzyna Zygnerska / Unsplash</figcaption></figure></section>`:v==='b'?`<section class="wrap"><div class="n-immersive"><img src="assets/dental-room-katarzyna.jpg" alt="Illustrative dental room">${nCopy}<span class="n-immersive-credit">Illustrative room · Katarzyna Zygnerska / Unsplash</span></div></section>`:`<section class="wrap n-index"><div>${nCopy}<p class="n-first-note">Your first visit begins with listening, then a discussion of the assessment and your options. You can ask questions or request a pause.</p><div class="n-index-links"><a href="#care">Everyday dental care ${arrow}</a><a href="#first-visit">Your first visit ${arrow}</a><a href="#questions">Questions, answered ${arrow}</a></div></div><figure><img src="assets/dental-consultation-harold.jpg" alt="Illustrative conversation between a dentist and a patient"><figcaption class="n-index-caption">Illustrative consultation photo · Harold Hisona / Unsplash<br>This stock image does not depict Noor staff or patients.</figcaption></figure></section>`;page('noor','Noor Dental — Care at your pace',`${nNav}<main id="main">${hero}${nRest}</main>`,nCSS+`.n-index{align-items:center;padding-top:20px}.n-index .n-copy h1{font-size:76px}.n-index figure{align-self:stretch;padding-top:36px}.n-index img{height:425px;object-position:center}.n-index-caption{font-size:11px;line-height:1.6;margin-top:12px;color:#4f6458}.n-index .quiet{display:none}.n-first-note{font-size:13px;line-height:1.7;max-width:410px;margin-top:22px}.n-index-links{margin-top:22px}.n-index-links a{padding:14px 0;font-size:13px}.n-immersive-credit{position:absolute;right:20px;bottom:12px;background:#fbfaf6;padding:6px;font-size:11px}.n-hero figcaption{font-size:11px}.n-copy p{font-size:15px}.n-service p{font-size:14px}.n-values p{font-size:13px}.n-form label{font-size:12px}@media(max-width:700px){.n-index{padding-top:10px;gap:26px}.n-index .n-copy h1{font-size:54px;letter-spacing:-2.7px;line-height:1.02;margin:10px 0 18px}.n-index .n-copy p{font-size:14px}.n-index .n-copy .btn{margin-top:20px}.n-first-note{font-size:13px;margin-top:19px}.n-index-links{margin-top:16px}.n-index figure{padding-top:0}.n-index img{height:275px}.n-index-caption{font-size:11px}.n-copy .urdu{font-size:18px}.n-values p{font-size:13px}.n-first .footnote{font-size:11px}}`,`const form=document.querySelector('#appointment-form');form.elements.day.min=new Date().toISOString().slice(0,10);form.addEventListener('submit',e=>{e.preventDefault();document.querySelector('#appointment-status').textContent='Your demo request is ready. No details were sent and no appointment is confirmed.';});`,v)}

