const hScript=`let ready=144;const toast=document.querySelector('#h-toast');document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.h-table tbody tr').forEach(r=>r.hidden=b.dataset.filter!=='all'&&r.dataset.status!==b.dataset.filter)}));document.querySelectorAll('.h-done').forEach(b=>b.addEventListener('click',()=>{const row=b.closest('tr');if(row.dataset.status==='queued'){row.dataset.status='baking';row.querySelector('.h-status').className='h-status baking';row.querySelector('.h-status').textContent='Baking';b.textContent='Mark ready';b.setAttribute('aria-label','Mark ready: '+row.children[0].firstChild.textContent);toast.hidden=false;toast.textContent=row.children[0].firstChild.textContent+' started baking in this local demo.';const active=document.querySelector('[data-filter][aria-pressed=true]');if(active.dataset.filter!=='all'&&active.dataset.filter!=='baking')row.hidden=true;return;}row.dataset.status='ready';row.querySelector('.h-status').className='h-status ready';row.querySelector('.h-status').textContent='Ready';b.disabled=true;b.textContent='Done ✓';const quantity=parseInt(row.children[1].textContent);ready+=quantity;document.querySelector('#pieces-ready').firstChild.textContent=ready;document.querySelector('#pieces-ready').nextElementSibling.textContent=Math.round(ready/248*100)+'% of today’s plan';toast.hidden=false;toast.textContent=row.children[0].firstChild.textContent+' marked ready. This change is local demo state.';const active=document.querySelector('[data-filter][aria-pressed=true]');if(active.dataset.filter!=='all'&&active.dataset.filter!=='ready')row.hidden=true;}));const dialog=document.querySelector('#batch-dialog');document.querySelector('#add-batch').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-batch').addEventListener('click',()=>dialog.close());document.querySelector('#batch-form').addEventListener('submit',e=>{e.preventDefault();dialog.close();toast.hidden=false;toast.textContent='New batch drafted: '+document.querySelector('#batch-product').value+' × '+document.querySelector('#batch-quantity').value+'. Not added to the production plan in this demo.';});`;
for(const v of ['a','b','c']){const stats=`<section class="h-stats" aria-label="Today's production summary"><div class="h-stat"><span class="label">Planned production</span><strong>248<span>pieces</span></strong><small>Across 5 batches</small></div><div class="h-stat"><span class="label">Ready for the counter</span><strong id="pieces-ready">144<span>pieces</span></strong><small class="good">58% of today's plan</small></div><div class="h-stat"><span class="label">Collection orders</span><strong>12<span>orders</span></strong><small>3 due before 11:00</small></div><div class="h-stat"><span class="label">Needs your attention</span><strong>2<span>items</span></strong><small class="warn">Stock running low</small></div></section>`;page('hearth','Hearth — Today’s bakery operations',`<div class="h-shell">${hSidebar}<main class="h-main" id="main"><header class="h-topbar"><span>Canal Street <span style="margin:0 9px;color:#999">/</span> Overview</span><div class="h-topbar-right"><span class="tag">Demo workspace</span><time datetime="2026-11-04T09:12">09:12 am</time></div></header><section class="h-heading"><div><span class="eyebrow" style="font-size:9px">Wednesday, 4 November · Morning shift</span><h1>A good day starts here.</h1><p>Your bake, your team, your next little thing.</p></div><button id="add-batch" class="btn"><span aria-hidden="true">＋</span> Add a batch</button></section>${stats}<div class="h-quick-status"><a href="#oven-status"><strong>Oven 01 · 230°C</strong><span>Sourdough · 12 min left</span></a><a href="#stock"><strong>2 low-stock items</strong><span>Butter & rye flour ↗</span></a></div><p id="h-toast" class="h-toast" hidden role="status"></p><div class="h-grid">${hTable}<div class="h-sidepanels">${hOvens}${hStock}</div></div><div class="h-lower">${hChart}${hCollections}</div><footer class="h-demo"><span>Fictional bakery · All names, quantities, stock and orders are demo data.</span><span>Changes stay in this page. No production system is connected.</span></footer></main></div><dialog id="batch-dialog" class="h-dialog"><form id="batch-form"><h2>A fresh batch.</h2><label for="batch-product">Product<select id="batch-product"><option>Country sourdough</option>Butter croissant</option>Cinnamon morning bun</option></select></label><label for="batch-quantity">Quantity<input id="batch-quantity" type="number" min="1" max="1000" value="24" required></label><p class="footnote" style="margin-bottom:20px">Draft a batch in this local demo. It will not change a live production plan.</p><button type="button" class="cancel" id="cancel-batch">Cancel</button><button type="submit">Draft batch</button></form></dialog>`,hCSS+`.h-mobile-quantity,.h-quick-status{display:none}.h-table td{font-size:12px}.h-table small{font-size:10px}.h-table th{font-size:10px}.h-done{font-size:11px;min-width:74px;min-height:36px}.h-status{font-size:10px}.h-panel h2{font-size:15px}.h-oven h3,.h-stock-row{font-size:13px}.h-oven p{font-size:11px}.h-topbar{font-size:12px}.h-stat .label{font-size:12px}.h-stat small{font-size:11px}.h-tabs button{font-size:11px;min-height:40px}@media(max-width:700px){.h-heading{padding:18px 0}.h-heading h1{font-size:26px}.h-heading p{margin-top:6px;font-size:11px}.h-stats{row-gap:17px;padding:16px 0}.h-stat strong{font-size:31px;margin-top:5px}.h-stat small{font-size:10px}.h-stat .label{font-size:11px}.h-mobile-quantity{display:inline;color:#303b2b;font-weight:bold}.h-quick-status{display:grid;grid-template-columns:1fr 1fr;gap:16px;background:#e9e6da;padding:15px 12px;margin-top:18px;border-radius:4px}.h-quick-status a{display:block;font-size:11px;line-height:1.6}.h-quick-status strong{display:block;font-weight:500}.h-quick-status span{font-size:10px;color:#5c6256}.h-grid{margin-top:18px}.h-table td{font-size:11px;padding:15px 9px}.h-table td:first-child{padding-left:12px}.h-table small{font-size:10px;line-height:1.5;white-space:normal}.h-table th{font-size:9px}.h-status{font-size:9px}.h-done{font-size:10px;min-width:64px}.h-tabs{padding-left:12px;padding-right:12px}.h-tabs button{font-size:10px;min-height:40px;padding:8px}.h-oven h3,.h-stock-row{font-size:13px}}`,hScript,v);if(v!=='a'){const f=path.join(root,'hearth',`concept-${v}.html`);fs.writeFileSync(f,fs.readFileSync(f,'utf8').replace(`class="variant-${v}"`,`class="variant-${v} ${v==='b'?'h-horizontal':'h-exception'}"`))}}
